import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
const [root, runtime] = process.argv.slice(2);
const load = rel => import(pathToFileURL(path.join(runtime, 'dist', rel)));
const { init: initLogger } = await load('logger/index.js'); process.env.LOG_LEVEL='error'; await initLogger();
const { getConfig } = await load('config/defaults.js');
const { GlobalConfig } = await load('config/global.js');
const { resolveConfigPresets } = await load('config/presets/index.js');
const { mergeChildConfig } = await load('config/utils.js');
const mem = await load('util/cache/memory/index.js');
const { getCache } = await load('util/cache/repository/index.js');
const { setPlatformApi } = await load('modules/platform/index.js');
const { platformScmImpls } = await load('modules/platform/scm.js');
const { LocalFs } = await load('modules/platform/local/scm.js');
const { processBranch } = await load('workers/repository/update/branch/index.js');
const { tryBranchAutomerge } = await load('workers/repository/update/branch/automerge.js');
class MissingBranchFixture extends LocalFs {
 branchExists() { return Promise.resolve(false); }
 commitAndPush() { throw new Error('Mutation attempted during evidence check'); }
 mergeAndPush() { throw new Error('Mutation attempted during evidence check'); }
 deleteBranch() { throw new Error('Mutation attempted during evidence check'); }
}
platformScmImpls.set('local', MissingBranchFixture);
const { extractPackageFile } = await load('modules/manager/github-actions/extract.js');
const { applyPackageRules } = await load('util/package-rules/index.js');
const { lookupUpdates } = await load('workers/repository/process/lookup/index.js');
const { branchifyUpgrades } = await load('workers/repository/updates/branchify.js');
const receiptPath = path.join(root, 'sources/evaluate/2026-10-08-runner-behavior-receipt.json');
const receipt = JSON.parse(fs.readFileSync(receiptPath));
GlobalConfig.set({ platform: 'local', dryRun: 'lookup', presetCachePersistence: false, localDir: '/tmp/renovate-runner-evidence-20261008', cacheDir: '/tmp/renovate-runner-evidence-20261008/cache' });
setPlatformApi('local');
getCache().semanticCommits = 'enabled';
const read = p => JSON.parse(receipt.preset_inputs[p].content);
const old = JSON.parse(receipt.before_preset.content);
const fields = ['depName','depType','datasource','currentValue','currentDigest','updateType','newValue','newVersion','groupName','groupSlug','branchName','dependencyDashboardApproval','automerge','pinDigests','labels','addLabels','skipReason','isDeprecated','enabled'];
const project = x => Object.fromEntries(fields.filter(k=>x[k]!==undefined).map(k=>[k,x[k]]));
async function resolve(consumer, variant) {
 mem.init();
 mem.set('preset:local>basher83/renovate-config',read('default.json'));
 for(const f of Object.keys(receipt.preset_inputs).filter(p=>p.startsWith('presets/')).map(p=>p.slice('presets/'.length))) {
  mem.set('preset:local>basher83/renovate-config//presets/'+f,variant==='before' && f==='github-actions-security.json' ? old : read('presets/'+f));
 }
 const {config,visitedPresets} = await resolveConfigPresets(JSON.parse(consumer.files.find(f=>f.path==='renovate.json').content));
 const merged = mergeChildConfig(getConfig(),config);
 merged.repository=consumer.repository; merged.repoIsOnboarded=true; merged.errors=[]; merged.warnings=[];
 return {config:merged,presets:[...visitedPresets.merged]};
}
const results=[];const presetSets={};
for(const consumer of receipt.consumers) {
 const extraction=[];
 for(const file of consumer.files.filter(f=>f.path.endsWith('.yml') || f.path.endsWith('.yaml'))) {
  const parsed=await extractPackageFile(file.content,file.path);
  if(parsed) extraction.push({packageFile:file.path,...parsed});
 }
 const before=await resolve(consumer,'before'); const after=await resolve(consumer,'after');
 let presetSet=Object.keys(presetSets).find(k=>JSON.stringify(presetSets[k])===JSON.stringify(after.presets));
 if(!presetSet) {presetSet=`set-${Object.keys(presetSets).length+1}`;presetSets[presetSet]=after.presets;}
 const comparisons=[]; const lookups=[];
 for(const file of extraction) for(const dep of file.deps) {
  for(const updateType of ['digest','patch','minor','major','pin','replacement']) {
   const left=await applyPackageRules({...before.config,...dep,packageName:dep.packageName??dep.depName,manager:'github-actions',packageFile:file.packageFile,updateType});
   const right=await applyPackageRules({...after.config,...dep,packageName:dep.packageName??dep.depName,manager:'github-actions',packageFile:file.packageFile,updateType});
   if(dep.depType==='github-runner') {
    assert.equal(right.groupSlug,'github-hosted-runners');assert.equal(right.dependencyDashboardApproval,true);assert.equal(right.automerge,false);
   } else { const a={...left};const b={...right};delete a.packageRules;delete b.packageRules;delete a.description;delete b.description;assert.deepEqual(a,b); }
   comparisons.push({packageFile:file.packageFile,kind:'hypothetical update-type control over actual extracted dependency',before:project(left),after:dep.depType==='github-runner'?project(right):{same_as:'before'}});
  }
  if(dep.depType==='github-runner' && !dep.skipReason) {
   const input=await applyPackageRules({...after.config,...dep,manager:'github-actions',packageName:dep.packageName??dep.depName,packageFile:file.packageFile});
   const lookupResult=(await lookupUpdates(input)).unwrap(); assert(lookupResult.ok,JSON.stringify(lookupResult)); const lookup=lookupResult.val;
   if(consumer.case==='preserved-pre-upgrade-replay-not-hosted-observation') assert(lookup.updates.length>0,'preserved runner must produce a real lookup update');
   lookups.push({packageFile:file.packageFile,dependency:dep,result:lookup});
  }
 }
 const files=structuredClone(extraction);
 for(const file of files) for(const dep of file.deps) {
  const real=lookups.find(x=>x.packageFile===file.packageFile && x.dependency.depName===dep.depName && x.dependency.currentValue===dep.currentValue);
  dep.updates=real?real.result.updates:dep.skipReason?[]:[{updateType:'digest',newDigest:'1111111111111111111111111111111111111111',newVersion:dep.currentValue,newValue:dep.currentValue}];
 }
 const groups={}; const approvalDispositions=[];
 for(const variant of ['before','after']) {
  const config=variant==='before'?before.config:after.config;
  const grouping=await branchifyUpgrades(config,structuredClone({'github-actions':files}));
  groups[variant]=grouping.branches.map(b=>({...project(b),upgrades:b.upgrades.map(project)}));
  if(variant==='after') for(const b of grouping.branches) {
   const runners=b.upgrades.filter(u=>u.depType==='github-runner');
   if(runners.length) {assert.equal(runners.length,b.upgrades.length);assert.equal(b.automerge,false);assert.equal(b.dependencyDashboardApproval,true);
    const result=await processBranch(b); assert.equal(result.result,'needs-approval');
    const automergeResult=await tryBranchAutomerge({...b,automergeType:'branch'});assert.equal(automergeResult,'no automerge');
    approvalDispositions.push({kind:'Real runner lookup branch with an explicit missing-branch/no-dashboard-check platform fixture',branchName:b.branchName,result,automergeResult});
   }
  }
 }
 const globalConfig=structuredClone(after.config);globalConfig.major={...globalConfig.major,automerge:true,dependencyDashboardApproval:false};
 const globalResult=await branchifyUpgrades(globalConfig,structuredClone({'github-actions':files}));
 for(const b of globalResult.branches.filter(b=>b.upgrades.some(u=>u.depType==='github-runner'))) {assert.equal(b.automerge,false);assert.equal(b.dependencyDashboardApproval,true);}
 const overrideConfig=structuredClone(after.config);overrideConfig.packageRules.push({matchManagers:['github-actions'],matchDepTypes:['github-runner'],automerge:true,dependencyDashboardApproval:false,groupName:'Consumer runner override',groupSlug:'consumer-runner-override'});
 const overrideResult=await branchifyUpgrades(overrideConfig,structuredClone({'github-actions':files}));
 for(const b of overrideResult.branches.filter(b=>b.upgrades.some(u=>u.depType==='github-runner'))) {assert.equal(b.automerge,true);assert.equal(b.dependencyDashboardApproval,false);assert(b.groupSlug.endsWith('consumer-runner-override')); }
 results.push({repository:consumer.repository,revision:consumer.revision,case:consumer.case,extraction,resolved_preset_set:presetSet,comparisons,real_runner_lookups:lookups,approval_dispositions:approvalDispositions,mixed_group_controls:{method:'Real runner lookup upgrades combined with explicitly hypothetical digest upgrades for actual non-runner dependencies',groups},global_major_override_control:globalResult.branches.filter(b=>b.upgrades.some(u=>u.depType==='github-runner')).map(project),later_local_override_control:overrideResult.branches.filter(b=>b.upgrades.some(u=>u.depType==='github-runner')).map(project)});
}
const fixture=`name: explicit-fixture\non: push\njobs:\n  controls:\n    runs-on: ubuntu-24.04\n    container: node:20\n    services:\n      db:\n        image: postgres:16\n    steps:\n      - uses: actions/checkout@v4\n      - uses: jdx/mise-action@v2\n        with:\n          version: 2026.10.2\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20.0.0\n      - uses: actions/setup-python@v5\n        with:\n          python-version: 3.12.0\n  reusable:\n    uses: example/workflows/.github/workflows/ci.yml@v1\n`;
const fixtureExtract=await extractPackageFile(fixture,'.github/workflows/fixture.yml');
const controlConsumer=receipt.consumers[0];
const fixtureBefore=await resolve(controlConsumer,'before');const fixtureAfter=await resolve(controlConsumer,'after');
const fixtureResults=[];
for(const dep of fixtureExtract.deps.filter(d=>d.depType!=='github-runner')) for(const updateType of ['digest','patch','minor','major']) {
 const input={...dep,packageName:dep.packageName??dep.depName,manager:'github-actions',updateType};
 const before=await applyPackageRules({...fixtureBefore.config,...input}); const after=await applyPackageRules({...fixtureAfter.config,...input});
 const a={...before};const b={...after};delete a.packageRules;delete b.packageRules;delete a.description;delete b.description;assert.deepEqual(a,b);fixtureResults.push({kind:'explicit fixture; hypothetical update type',before:project(before),after:{same_as:'before'}});
}
const mixedMajorControls=[];
const replayLookup=results.find(r=>r.case==='preserved-pre-upgrade-replay-not-hosted-observation').real_runner_lookups[0].result;
for(const consumer of receipt.consumers.filter(c=>c.case==='fresh-default-branch-head')) {
 const before=await resolve(consumer,'before');const after=await resolve(consumer,'after');
 const files=structuredClone([{packageFile:'.github/workflows/fixture.yml',...fixtureExtract}]);
 for(const dep of files[0].deps) dep.updates=dep.depType==='github-runner'?replayLookup.updates:[{updateType:'major',newVersion:'99.0.0',newValue:dep.currentValue?.startsWith('v')?'v99.0.0':'99.0.0'}];
 const groups={};
 for(const [name,cfg] of [['before',before.config],['after',after.config]]) {
  const grouping=await branchifyUpgrades(cfg,structuredClone({'github-actions':files}));
  groups[name]=grouping.branches.map(b=>({...project(b),upgrades:b.upgrades.map(project)}));
  if(name==='before') assert(grouping.branches.some(b=>b.upgrades.some(u=>u.depType==='github-runner') && b.upgrades.some(u=>u.depType!=='github-runner')));
  else for(const b of grouping.branches.filter(b=>b.upgrades.some(u=>u.depType==='github-runner'))) { assert(b.upgrades.every(u=>u.depType==='github-runner'));assert.equal(b.automerge,false);assert.equal(b.dependencyDashboardApproval,true); }
 }
 mixedMajorControls.push({repository:consumer.repository,revision:consumer.revision,kind:'Explicit fixture with real ubuntu lookup and hypothetical major non-runner updates; verifies baseline mixed group and candidate isolation including repeated preset inheritance',groups});
}
const unsupported=`name: unsupported-fixture\non: push\njobs:\n  alias:\n    runs-on: ubuntu-latest\n    steps: []\n  self:\n    runs-on: [self-hosted, linux, x64]\n    steps: []\n  expression:\n    runs-on: \${{ matrix.os }}\n    steps: []\n`;
const unsupportedExtract=await extractPackageFile(unsupported,'.github/workflows/unsupported.yml');
assert(!(unsupportedExtract?.deps??[]).some(d=>d.depType==='github-runner' && !d.skipReason));
receipt.renovate={version:JSON.parse(fs.readFileSync(path.join(runtime,'package.json'))).version,node:process.version,source:'https://github.com/renovatebot/renovate/tree/44.145.1',execution:'Direct calls to installed Renovate extraction, preset resolution, lookupUpdates, package-rule application, and branchifyUpgrades APIs; platform=local, dryRun=lookup. No platform branch/PR/dashboard mutation API invoked.',preset_resolution:'Repository preset bodies supplied from exact local before/after bytes in Renovate memory cache; built-in presets resolved by Renovate. This changes no consumer file or external preset.'};
receipt.results=results;receipt.resolved_preset_sets=Object.fromEntries(Object.entries(presetSets).map(([key,names])=>[key,{visited_count:names.length,visited_names_sha256:createHash('sha256').update(JSON.stringify(names)).digest('hex'),root_and_shared_presets:names.filter(n=>n.startsWith('local>') || n==='config:best-practices' || n==='workarounds:all'),note:'Full internally visited preset names are summarized by count and hash; exact built-in resolution is reproducible with the pinned Renovate version and recipe.'}]));receipt.fixture_controls={content:fixture,extraction:fixtureExtract,comparisons:fixtureResults,unsupported_content:unsupported,unsupported_extraction:unsupportedExtract??null,mixed_major_controls:mixedMajorControls};
receipt.completed_at=new Date().toISOString();receipt.comparison_scope='Full returned dependency configurations compared for every non-runner case after removing the intentionally differing packageRules list and descriptive metadata; projections retained for readability; unchanged after projections refer to before rather than duplicating it. Mixed grouping uses real runner lookups and explicitly hypothetical non-runner upgrades.';receipt.harness_source=fs.readFileSync(new URL(import.meta.url),'utf8');
fs.writeFileSync(receiptPath,JSON.stringify(receipt,null,2)+'\n');
process.stdout.write(JSON.stringify({consumers:results.map(r=>({repo:r.repository,extracted:r.extraction.reduce((n,f)=>n+f.deps.length,0),real_runner_lookups:r.real_runner_lookups.map(x=>({input:x.dependency.currentValue,updates:x.result.updates})),branches:r.mixed_group_controls.groups.after.map(b=>({name:b.branchName,approval:b.dependencyDashboardApproval,automerge:b.automerge,types:[...new Set(b.upgrades.map(u=>u.depType))]}))})),fixture_dep_types:[...new Set(fixtureExtract.deps.map(d=>d.depType))],status:'passed'},null,2)+'\n');

