{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "description": "GitHub Actions security preset - pins action digests, selectively auto-merges action updates, and requires approval and manual merge for hosted runner updates",
  "packageRules": [
    {
      "description": "Pin GitHub Actions (uses:) to commit SHA digests for security",
      "matchManagers": [
        "github-actions"
      ],
      "matchDepTypes": [
        "action"
      ],
      "pinDigests": true
    },
    {
      "description": "Group all GitHub Actions updates together",
      "matchManagers": [
        "github-actions"
      ],
      "groupName": "GitHub Actions",
      "groupSlug": "github-actions"
    },
    {
      "description": "Auto-merge ALL GitHub Actions digest updates into main (no approval)",
      "matchManagers": [
        "github-actions"
      ],
      "matchUpdateTypes": [
        "digest"
      ],
      "automerge": true
    },
    {
      "description": "Auto-merge non-sensitive GitHub Actions patch, minor, and major updates into main (no approval)",
      "matchManagers": [
        "github-actions"
      ],
      "matchUpdateTypes": [
        "patch",
        "minor",
        "major"
      ],
      "matchPackageNames": [
        "!/^actions\\/checkout/",
        "!/^actions\\/upload-artifact/",
        "!/^actions\\/download-artifact/",
        "!/^aws-actions\\//",
        "!/^google-github-actions\\//",
        "!/^azure\\//",
        "!/^docker\\//"
      ],
      "automerge": true
    },
    {
      "description": "Require approval for security-sensitive GitHub Actions minor and major updates",
      "matchManagers": [
        "github-actions"
      ],
      "matchUpdateTypes": [
        "major",
        "minor"
      ],
      "dependencyDashboardApproval": true,
      "matchPackageNames": [
        "/^actions\\/checkout/",
        "/^actions\\/upload-artifact/",
        "/^actions\\/download-artifact/",
        "/^aws-actions\\//",
        "/^google-github-actions\\//",
        "/^azure\\//",
        "/^docker\\//"
      ]
    },
    {
      "description": "Label GitHub Actions PRs",
      "matchManagers": [
        "github-actions"
      ],
      "addLabels": [
        "github-actions",
        "security"
      ]
    },
    {
      "description": "Require dashboard approval and manual merge for GitHub-hosted runner updates",
      "matchManagers": ["github-actions"],
      "matchDepTypes": ["github-runner"],
      "groupName": "GitHub-hosted runners",
      "groupSlug": "github-hosted-runners",
      "dependencyDashboardApproval": true,
      "automerge": false
    }
  ]
}

